function pb.model(Zr,as,bs)
local cs=tostring(Zr)..XSe[2512]..tostring(bs and bs.atk)..XSe[2512]..tostring(bs and bs.cd)
local ds=pb._model[cs]
if ds~=nil then
return ds or nil
end
local es,fs={},false
local gs=math.max(0.3,tonumber(bs and bs.cd)or 2)
local hs=math.min(1,(tonumber(as and as.n)or 1)/4)
local js,ks=pcall(pb.guess,Zr)
local ls,ms={},{}
for ns,ps in ipairs(js and type(ks)==XSe[2370]and ks or{})do
if ps.hand then
ls[ps.pid]=true
end
ms[ps.pid]=ps.nums
end
for qs,rs in pairs(pb.rules(Zr))do
if not ls[qs]then
local ss={}
for ts,us in pairs(type(ms[qs])==XSe[2370]and ms[qs]or{})do
ss[ts]=us
end
for vs,ws in pairs(type(rs.nums)==XSe[2370]and rs.nums or{})do
ss[vs]=ws
end
local xs=rs.trigger~=nil and tostring(rs.trigger):find(XSe[2788],1,true)~=nil
if rs.family==XSe[2570]then
local ys=(xs and pb.ABILITY_UPTIME or 1)*(rs.who==XSe[2638]and pb.RANGE_SHARE or 1)
local zs=es.aura or{typed={}}
for As,Bs in pairs(type(ss.typed)==XSe[2370]and ss.typed or{})do
zs.typed[As]=math.max(zs.typed[As]or 0,(tonumber(Bs)or 0)*ys)
end
local Cs=tonumber(ss.dmgMax)or tonumber(ss.dmg)
if Cs then
zs.dmg=math.max(zs.dmg or 0,Cs*ys)
end
if ss.crit then
zs.crit=math.max(zs.crit or 0,(tonumber(ss.crit)or 0)*ys)
end
es.aura,fs=zs,true
elseif rs.family==XSe[2567]then
local Ds=pb.KW[tostring(rs.keyword or XSe[1289])]
local Es=tonumber(ss.chance)or 1
local Fs=tonumber(ss.secsSeen)or tonumber(ss.secs)or 5
local Gs=ss.keep or ss.keepSeen
local Hs=Gs and math.min(1,Es*4)or math.min(1,Fs*Es/gs)
if xs then
Hs=math.min(Hs,Fs/60)
end
if Ds and Ds.kind==XSe[2557]and not(type(ss.shred)==XSe[2370])then
local Is=tonumber(ss.amp)
local Js=as and((type(as.ampTypes)==XSe[2370]and as.ampTypes[Ds.dtype])or(tonumber(as.amp)or 0)>0)
if Is and Is>0 and not Js then
es.fx,fs=(es.fx or 0)+Is*V.TYPED_AMP_SHARE*Hs*hs,true
end
elseif Ds and(Ds.kind==XSe[2505]or Ds.kind==XSe[2565])then
if not(as and((tonumber(as.stun)or 0)>0 or(tonumber(as.slowTime)or 0)>0))then
es.stun=(Ds.kind==XSe[2565]and 0.5 or 1)*Fs
if ss.slow then
es.slowP,es.slowT=tonumber(ss.slow),Fs
end
fs=true
end
elseif Ds and Ds.kind==XSe[2507]then
if not(as and(tonumber(as.slowTime)or 0)>0)then
es.slowP,es.slowT,fs=tonumber(ss.slow)or tonumber(ss.slowSeen)or 0.3,Fs,true
end
elseif Ds and Ds.kind==XSe[2564]then
