function mb.weatherStrength(BE)
local CE=mb.fx(BE)
local DE=CE.dmg/CE.cd/CE.hp/CE.speed*(1+(CE.range-1)/2)
for EE,FE in pairs(CE.kinds)do
DE=DE*(1+bb.rogueShare(EE)*FE)
end
if CE.ice>0 then
local GE=bb.rogueShare(XSe[2521])
DE=DE*(GE+(1-GE)/(1-CE.ice+CE.ice/gb.modFactor(XSe[2929])))
end
if CE.fly>0 then
DE=DE*(1-CE.fly*0.5)
end
if CE.noCC then
DE=DE*0.95
end
if CE.shroud then
DE=DE*0.9
end
if CE.zap then
DE=DE*0.85
end
return DE/mb.weatherK(BE)
end
