tG[vG.unit_id]=tonumber(mG[vG.unit_id])or(((tonumber(pG[V.name(vG.unit_id)])or 0)+(tonumber(pG[XSe[2956]..tostring(vG.unit_id)])or 0))/math.max(1,qG))
