LG[FG[KG].i]=AG.u
if mb.teamDrop(LG,MF)>mb.teamDrop(jG,MF)+1e-6 and NF(LG,UF)then
table.insert(kG,string.format(XSe[2957],V.name(AG.u.unit_id),V.name(MG.unit_id)))
jG,yG=LG,true
wG=nG(jG)
break
end
end
end
if yG then
break
end
end
if not yG then
break
end
end
if#kG==0 then
return nil
end
return jG,string.format(XSe[2958],table.concat(kG,XSe[2494]),math.floor(mb.teamDrop(jG,MF)*100+0.5),math.floor(lG*100+0.5),UF)
