local Cdb=type(Adb)==XSe[2370]and tonumber(Adb.price)or nil
if Bdb and Cdb and Cdb<=xdb then
local Ddb=tdb[Adb.item_id]or 0
if udb<wdb or Ddb==0 then
if not ydb or Ddb<ydb.have or(Ddb==ydb.have and Bdb<ydb.pr)then
ydb={index=zdb,item_id=Adb.item_id,price=Cdb,have=Ddb,pr=Bdb}
