ab.DEF_REPAIR_AT=0.25
function ab.defRepairPlan(ieb,jeb,keb,leb)
local meb={}
for neb,oeb in ipairs(ieb)do
local peb=math.max(1,tonumber(oeb.max)or 1)
local qeb=math.max(0,tonumber(oeb.d)or peb)
if qeb<=peb*ab.DEF_REPAIR_AT then
local reb=tonumber(leb(oeb.item_id,qeb))or 0
if reb>0 then
table.insert(meb,{uuid=oeb.uuid,item_id=oeb.item_id,cost=reb})
end
end
end
table.sort(meb,function(seb,teb)
return seb.cost<teb.cost
end)
local ueb,veb,web=math.max(0,jeb-math.max(0,tonumber(keb)or 0)),{},0
for xeb,yeb in ipairs(meb)do
if yeb.cost<=ueb then
ueb=ueb-yeb.cost
web=web+yeb.cost
table.insert(veb,yeb)
end
end
return veb,web
end
