if Ugb and(Ugb.rarity==XSe[2961]or Ugb.rarity==XSe[3492])and not Fgb[Tgb.unit_id]and V.rows(Tgb.unit_id)and not V.hidden(Tgb.unit_id)and not V.isFarm(Tgb.unit_id)and not V.allyBuff(Tgb.unit_id)then
