function kb.gainXp(dhb,ehb)
local fhb,ghb=tonumber(dhb.xp)or 0,kb.xpFor(dhb.unit_id,kb.cap(dhb))
local hhb=math.max(0,ghb-fhb)
if hhb<=0 or(ehb or 0)<=0 then
return 0,0
end
local ihb=math.min(ehb,hhb)
local jhb=kb.base(dhb)
if jhb<=0 then
return 0,ihb
end
return kb.share(dhb.unit_id)*(kb.score(kb.whatIf(dhb,{xp=fhb+ihb}))/jhb-1)*100,ihb
end
