function kb.relicWorth(khb,lhb)
local mhb=lhb._unique_item_data and lhb._unique_item_data._unique_relic_data
if not mhb then
return 0
end
local nhb=N.Items[lhb.item_id]or{}
local ohb,phb=V.types(khb.unit_id)
if nhb.main_damage_type and nhb.main_damage_type~=XSe[3081]and nhb.main_damage_type~=phb then
return 0
end
local qhb,rhb=0,0
for shb,thb in pairs(mhb._core_damage_type_buffs or{})do
if ohb[thb.damage_type]then
qhb=qhb+(tonumber(thb.mul)or 0)+(tonumber(thb.add_upg)or 0)*0.01+(tonumber(thb.pen)or 0)*0.001
rhb=rhb+(tonumber(thb.crit)or 0)
end
end
qhb=qhb+rhb*0.5
local uhb=V.rows(khb.unit_id)
local vhb=uhb and uhb[uhb.max]
local whb=(vhb and tonumber(vhb.cd)or 0)*V.mult(khb,XSe[2821])
for xhb,yhb in pairs(mhb._unique_relic_effects or{})do
local zhb=type(yhb.params)==XSe[2370]and yhb.params or{}
if yhb.id==XSe[3494]then
local Ahb=math.min(1,(tonumber(zhb.extra_damage)or 0)*whb/math.max(1,tonumber(zhb.time_interval)or 40))
local Bhb=V.DRONES and V.DRONES[khb.unit_id]
if Bhb and Bhb.late and whb>0 then
local Chb=1/whb
Ahb=Ahb*Chb/(Chb+(tonumber(Bhb.max)or 0)*(tonumber(Bhb.late.dmg)or 0)*(tonumber(Bhb.hits)or 1)/math.max(0.1,tonumber(Bhb.late.cd)or 4))
end
qhb=qhb+Ahb
elseif yhb.id==XSe[3495]then
qhb=qhb+(tonumber(zhb.dmg_buff)or 0)*0.25
elseif yhb.id==XSe[3496]then
qhb=qhb+(tonumber(zhb.dmg_buff)or 0)*rhb
elseif yhb.id==XSe[3497]then
if ohb.magic then
qhb=0
else
qhb=qhb+(tonumber(zhb.dmg_buff)or 0)*0.3
end
elseif yhb.id==XSe[3498]then
if ohb.water_damage then
qhb=qhb+0.05
end
elseif yhb.id==XSe[2522]then
local Dhb=tonumber(zhb.duration_buff)or tonumber(type(yhb.static_params)==XSe[2370]and yhb.static_params.duration_buff)or 2
local Ehb,Fhb=pcall(V.attackInfo,vhb and vhb.atk,vhb and vhb.range)
local Ghb,Hhb=Ehb and tonumber(Fhb.burn)or 0,Ehb and tonumber(Fhb.dot)or 0
if Ghb<=0 then
local Ihb,Jhb=pcall(pb.model,khb.unit_id,Ehb and Fhb or nil,vhb)
if Ihb and type(Jhb)==XSe[2370]and(tonumber(Jhb.burnDot)or 0)>0 then
Ghb,Hhb=Jhb.burnDot,Hhb+(tonumber(Jhb.dot)or 0)
