local Xhb=kb.relicWorth(Rhb.u,Whb)*Thb*100
if Xhb>0.01 then
table.insert(Uhb,{it=Whb,w=Xhb})
end
end
table.sort(Uhb,function(Yhb,Zhb)
if Yhb.w~=Zhb.w then
return Yhb.w>Zhb.w
end
return Yhb.it.uuid<Zhb.it.uuid
end)
local aib,bib={},{}
for cib,dib in ipairs(Uhb)do
local eib=bib[dib.it.item_id]or 0
if#aib<6 and eib<((N.Items[dib.it.item_id]or{}).unique_equip and 1 or 2)then
bib[dib.it.item_id]=eib+1
table.insert(aib,dib)
end
end
if Rhb.u._equipped_relic then
local fib=false
for gib,hib in ipairs(aib)do
if hib.it.uuid==Rhb.u._equipped_relic then
fib=true
end
end
local iib=not fib and Khb.inventory:get_item_by_uuid(Rhb.u._equipped_relic)
if iib then
table.insert(aib,{it=iib,w=kb.relicWorth(Rhb.u,iib)*Thb*100})
