local uib=(N.Items[tib.it.item_id]or{}).unique_equip
if not mib[tib.it.uuid]and not(uib and nib[tib.it.item_id])then
mib[tib.it.uuid]=true
if uib then
nib[tib.it.item_id]=true
end
lib[rib.e.uuid]=tib.it.uuid
oib(pib+1,qib+tib.w+(tib.it.uuid==rib.e.u._equipped_relic and 0.01 or 0))
lib[rib.e.uuid]=nil
mib[tib.it.uuid]=nil
if uib then
nib[tib.it.item_id]=nil
end
end
end
end
oib(1,0)
local vib,wib=0,{}
for xib,yib in ipairs(Phb)do
local zib=yib.e.u._equipped_relic and Khb.inventory:get_item_by_uuid(yib.e.u._equipped_relic)
local Aib=zib and kb.relicWorth(yib.e.u,zib)*yib.share*100 or 0
