end
local Nnb={}
local function Onb(Pnb)
local Qnb=Pnb and N.Units[Pnb.unit_id]
local Rnb=Qnb and Qnb.evolve and(Pnb.shiny and Qnb.evolve.shiny or Qnb.evolve.normal)
for Snb,Tnb in pairs(type(Rnb)==XSe[2370]and type(Rnb.unit_requirement)==XSe[2370]and Rnb.unit_requirement or{})do
if type(Tnb)==XSe[2370]and Tnb.unit_id then
