local Znb=Ynb and ab.FUSE_RANK[Ynb.rarity]
if Znb and Znb<=Fnb and not Gnb[Wnb]and(Nnb[Xnb.unit_id]or 0)>0 then
Nnb[Xnb.unit_id]=Nnb[Xnb.unit_id]-1
Znb=nil
end
if Znb and Znb<=Fnb and not Gnb[Wnb]then
local _nb=Enb.collection:get_unit_by_uuid(Wnb)or Xnb
if not(Xnb._locked or _nb._locked)and not(Xnb._equipped_relic or _nb._equipped_relic)then
local aob,bob=pcall(N.USC.calculate_xp_gain_from_fuse,Dnb,{_nb},Enb)
bob=aob and tonumber(bob)or 0
if bob>0 then
table.insert(Unb,{uuid=Wnb,id=Xnb.unit_id,xp=bob,rarity=Ynb.rarity})
Vnb=Vnb+bob
end
end
end
end
table.sort(Unb,function(cob,dob)
if cob.xp~=dob.xp then
return cob.xp<dob.xp
end
return cob.uuid<dob.uuid
end)
local eob=math.max(0,kb.xpFor(Dnb.unit_id,kb.cap(Dnb))-(tonumber(Dnb.xp)or 0))
local fob,gob={},0
for hob,iob in ipairs(Unb)do
if gob>=eob then
break
end
