return WNb.gain/WNb.cost>XNb.gain/XNb.cost
end)
local YNb,ZNb=0,0
for _Nb,aOb in ipairs(TNb)do
if SNb<=0 then
break
end
ZNb=aOb.gain/aOb.cost
local bOb=math.min(1,SNb/aOb.cost)
YNb=YNb+aOb.gain*bOb
SNb=SNb-aOb.cost*bOb
