if Npc.strong and Npc.strong[jqc]then
table.insert(Wpc,string.format(XSe[4377],Lpc(jqc)))
end
if#Wpc==0 then
table.insert(Wpc,XSe[4378])
end
local oqc,pqc,qqc=pcall(V.mapNudge,Vpc,Jpc and Jpc.map,Jpc and Jpc.mapSig)
local rqc=oqc and type(qqc)==XSe[2370]and(tonumber(qqc.n)or 0)or 0
