function jb.sim(_vc,awc,bwc)
if not O.sim or type(_vc.r._l)~=XSe[2370]then
return nil
end
local cwc=tostring(_vc.r._r or(_vc.d..XSe[2523].._vc.choice))..(awc and(XSe[2700]..tostring(awc))or XSe[1289])..(bwc and XSe[4491]or XSe[1289])
local dwc=jb.data()
local ewc=jb.fx(dwc,jb.roomCurse(_vc.r),awc)
local fwc=W.teamSig()..XSe[2383]..jb.fxText(ewc)..(O.killZone~=false and XSe[4492]or XSe[1289])..(bb.forcedWay()and(XSe[2383]..tostring(O.placeMode))or XSe[1289])
local gwc=P.dg.sim[cwc]
if gwc and gwc.sig==fwc then
return not gwc.none and gwc or nil
end
local hwc={}
for iwc,jwc in ipairs(V.equipped())do
table.insert(hwc,jwc.u)
end
if#hwc==0 then
return nil
end
local kwc=gb.applyFx(gb.info(gb.slim(_vc.r._l),XSe[3141],nil,jb.mod(_vc.r._l)),ewc)
jb.applyK(kwc,_vc.r._r)
if bwc then
kwc.zone=false
end
local lwc=gb.wave(kwc,1,true)
if#lwc==0 then
gwc={none=true,sig=fwc,at=os.time()}
else
local mwc=gb.evaluate(kwc,gb.teamFrom(hwc,kwc.map))
gwc={p=mwc.p,wave=mwc.wave,won=mwc.won,total=kwc.total,margin=mwc.margin,sig=fwc,at=os.time(),zone=kwc.zone~=false or nil}
end
P.dg.sim[cwc]=gwc
if U.count(P.dg.sim)>60 then
local nwc,owc
for pwc,qwc in pairs(P.dg.sim)do
if not owc or(qwc.at or 0)<owc then
nwc,owc=pwc,qwc.at or 0
end
end
P.dg.sim[nwc]=nil
end
F.saveSoon()
return not gwc.none and gwc or nil
end
function jb.winP(rwc)
local swc=tostring(math.min(4,math.max(1,math.ceil(rwc.d/5))))
local twc=P.dg.depth[swc]or{runs=0,wins=0}
local uwc=U.clamp(0.95-0.015*rwc.d,0.5,0.95)
local vwc=((tonumber(twc.wins)or 0)+uwc*2)/((tonumber(twc.runs)or 0)+2)
local wwc,xwc=pcall(jb.sim,rwc)
if wwc and xwc and xwc.p then
local ywc,zwc=pcall(gb.styleP,xwc,xwc.zone==false and XSe[4324]or(xwc.zone and XSe[4258]or nil))
vwc=(vwc*2+(ywc and zwc or xwc.p))/3
end
return vwc,wwc and xwc or nil
end
function jb.hopeless(Awc)
