end
function jb.curseOk(Kwc,Lwc,Mwc,Nwc,Owc)
local Pwc=tostring((jb.item(Kwc)or{}).name or Kwc)
local Qwc,Rwc,Swc=jb.curseBar(Lwc,Mwc)
if Qwc>0.2 and jb.blindCurse(Lwc,Kwc)then
return false,string.format(XSe[4496],Pwc,Swc)
end
local function Twc(Uwc)
return Uwc==nil or(tonumber(Uwc.p)or 1)>=Qwc
end
if Nwc then
local Vwc,Wwc=pcall(jb.sim,Nwc,nil,true)
if Vwc and not Twc(Wwc)then
return false,string.format(XSe[4497],Pwc,(Rwc:gsub(XSe[4090],XSe[4498])),tostring(Wwc.margin or XSe[2621]))
end
end
if#Owc==0 then
return true
end
local Xwc
for Ywc,Zwc in ipairs(Owc)do
local _wc,axc=pcall(jb.sim,Zwc,Kwc,true)
if not _wc or Twc(axc)then
return true
end
if not Xwc or(tonumber(axc.p)or 0)>(tonumber(Xwc.p)or 0)then
Xwc=axc
end
end
return false,string.format(XSe[4499],Pwc,Rwc,tostring(Xwc and Xwc.margin or XSe[2621]))
end
function jb.curseGate(bxc,cxc)
