end
function jb.payValue()
local exc,fxc=0,0
for gxc,hxc in ipairs(P.dg.pay or{})do
if type(hxc.items)==XSe[2370]then
local ixc=tonumber(hxc.gems)or 0
for jxc,kxc in pairs(hxc.items)do
if(tonumber(kxc)or 0)>0 then
ixc=ixc+W.itemValue(jxc,kxc)
end
end
exc,fxc=exc+ixc,fxc+1
end
end
if fxc<5 then
return nil
end
return exc/fxc*0.7
