jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
local lxc=type(P.dg)==XSe[2370]and type(P.dg.lossCalls)==XSe[2370]and P.dg.lossCalls or{}
return U.clamp(((tonumber(lxc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(lxc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
end
function jb.pick(mxc)
local nxc,oxc=jb.curses(mxc),jb.lives(mxc)
local pxc=jb.res(mxc)
local qxc=jb.rooms(mxc)
local rxc={}
for sxc,txc in ipairs(qxc)do
table.insert(rxc,tostring(txc.r._r))
end
local uxc=table.concat(rxc,XSe[3077])..string.format(XSe[4500],oxc,pxc,nxc,W.teamSig())
if jb._pick and jb._pick.sig==uxc then
return jb._pick.x
end
local vxc,wxc,xxc,yxc
for zxc,Axc in ipairs(qxc)do
local Bxc=jb.roomValue(Axc,pxc)
local Cxc,Dxc
for Exc,Fxc in ipairs(jb.after(mxc,Axc.choice))do
local Gxc=jb.roomValue(Fxc,pxc)
if not Cxc or Gxc>Cxc then
Cxc,Dxc=Gxc,Fxc
end
end
local Hxc,Ixc=jb.winP(Axc)
local Jxc=Ixc~=nil and Ixc.won==false
local Kxc=oxc>=3 and 1 or(oxc==2 and 2 or 6)
local Lxc=1-(1-Hxc)^math.max(1,oxc)
Axc.oldScore=Lxc*(Bxc+0.6*(Cxc or 0))-(1-Hxc)*Kxc
if Jxc then
Hxc=math.min(Hxc,jb.lossWin())
Lxc=Hxc
Kxc=Kxc*2
end
Axc.p,Axc.sim,Axc.value,Axc.nextValue,Axc.nextRoom,Axc.simLost=Hxc,Ixc,Bxc,Cxc or 0,Dxc,Jxc or nil
Axc.score=Lxc*(Bxc+0.6*(Cxc or 0))-(1-Hxc)*Kxc
local Mxc,Nxc,Oxc=pcall(jb.curseGate,Axc,mxc)
if Mxc and not Nxc then
Axc.blocked=Oxc
end
if not Axc.blocked then
if not vxc or Axc.score>vxc.score then
vxc=Axc
end
if Jxc then
if not yxc or Axc.score>yxc.score then
yxc=Axc
end
elseif not xxc or Axc.score>xxc.score then
xxc=Axc
end
end
if not wxc or Axc.score>wxc.score then
wxc=Axc
end
end
if vxc and vxc.simLost and xxc then
F.log(1,XSe[4501],string.format(XSe[4502],jb.roomName(vxc),tostring(vxc.sim and vxc.sim.margin or XSe[2621]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(xxc)))
elseif vxc and yxc and yxc~=vxc and yxc.oldScore>vxc.score then
F.log(1,XSe[4501],string.format(XSe[4503],jb.roomName(yxc),tostring(yxc.sim and yxc.sim.margin or XSe[2621]),jb.roomName(vxc)))
end
vxc=vxc or wxc
jb._pick={sig=uxc,x=vxc,rooms=qxc}
return vxc
end
