function jb.roomLearn(QEc)
if QEc or bb.kind~=XSe[2396]or bb.roomLearned then
return
end
local REc=P.dg.room
local SEc,TEc=bb.pred,bb.calRun
if type(REc)~=XSe[2370]or REc.seed==nil or type(SEc)~=XSe[2370]or not SEc.won or type(TEc)~=XSe[2370]then
return
end
local function UEc(VEc,WEc)
return type(VEc)==XSe[2370]and tonumber(VEc[WEc]or VEc[tostring(WEc)])or nil
end
local XEc={}
for YEc=2,bb.wave()do
local ZEc,_Ec=UEc(TEc.alive,YEc),UEc(SEc.aliveAt,YEc)
if ZEc and _Ec and ZEc>0 and _Ec>0 then
table.insert(XEc,ZEc/_Ec)
end
end
if#XEc<3 then
return
end
table.sort(XEc)
local aFc=XEc[math.ceil(#XEc/2)]
bb.roomLearned=true
if aFc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==XSe[2370]and P.dg.roomK or{}
local bFc=tostring(REc.seed)
local cFc=P.dg.roomK[bFc]
local dFc=math.min(jb.ROOM_K_MAX,jb.roomK(bFc)*aFc)
P.dg.roomK[bFc]={k=dFc,n=(type(cFc)==XSe[2370]and tonumber(cFc.n)or 0)+1,at=os.time(),d=REc.d}
bb.roomKUp=true
