table.insert(eFc,{s=fFc,at=type(gFc)==XSe[2370]and tonumber(gFc.at)or 0})
end
table.sort(eFc,function(hFc,iFc)
return hFc.at>iFc.at
end)
for jFc=31,#eFc do
P.dg.roomK[eFc[jFc].s]=nil
end
F.log(1,XSe[4501],string.format(XSe[4623],tostring(REc.d),aFc,dFc))
end
