function bb.buildPath()
bb.samples={}
local MFc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not MFc then
return
end
for NFc,OFc in pairs(MFc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[NFc.Name])then
local PFc={}
for QFc,RFc in ipairs(OFc.points or{})do
table.insert(PFc,RFc.part.Position)
end
local SFc=0
for TFc=2,#PFc do
SFc=SFc+(PFc[TFc]-PFc[TFc-1]).Magnitude
end
local UFc=0
for VFc=2,#PFc do
local WFc,XFc=PFc[VFc-1],PFc[VFc]
local YFc=(XFc-WFc).Magnitude
local ZFc=math.max(1,math.floor(YFc/2))
for _Fc=0,ZFc-1 do
local aGc=WFc:Lerp(XFc,_Fc/ZFc)
table.insert(bb.samples,{pos=aGc,prog=(UFc+YFc*_Fc/ZFc)/math.max(1,SFc),lane=NFc.Name})
end
UFc=UFc+YFc
end
if PFc[#PFc]then
table.insert(bb.samples,{pos=PFc[#PFc],prog=1,lane=NFc.Name})
end
end
end
pcall(bb.readHidden,MFc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local bGc=tonumber(bb.ld and bb.ld._portal_lanes)
local cGc=gb.laneList(bb.samples)
if bGc and bGc>=1 and cGc and#cGc>bGc then
bb.laneWant=bGc
end
bb.laneTotal=cGc and#cGc or 1
bb.countLanes()
end
function bb.readHidden(dGc)
local eGc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(eGc)~=XSe[2370]or not next(eGc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local fGc
for gGc,hGc in pairs(dGc)do
if eGc[gGc.Name]and type(hGc.points)==XSe[2370]and#hGc.points>=2 then
local iGc={}
for jGc,kGc in ipairs(hGc.points)do
iGc[jGc]=U.flat(kGc.part.Position)
end
local lGc={}
for mGc,nGc in ipairs(bb.samples)do
local oGc=tostring(nGc.lane)
lGc[oGc]=lGc[oGc]or{}
table.insert(lGc[oGc],nGc)
end
local pGc,qGc
for rGc,sGc in pairs(lGc)do
local tGc=0
for uGc=1,#iGc,math.max(1,math.floor(#iGc/20))do
local vGc=math.huge
for wGc,xGc in ipairs(sGc)do
local yGc=(U.flat(xGc.pos)-iGc[uGc]).Magnitude
if yGc<vGc then
vGc=yGc
end
end
tGc=tGc+vGc
end
if not qGc or tGc<qGc then
pGc,qGc=rGc,tGc
end
end
local zGc,AGc,BGc,CGc,DGc,EGc={},nil,nil,nil,0,0
for FGc,GGc in ipairs(iGc)do
local HGc,IGc=nil,math.huge
for JGc,KGc in ipairs(lGc[pGc])do
local LGc=(U.flat(KGc.pos)-GGc).Magnitude
if LGc<IGc then
IGc,HGc=LGc,KGc.prog
end
end
EGc=math.max(EGc,IGc)
if BGc then
local MGc=HGc-BGc
local NGc=(MGc>0.002 and 1)or(MGc< -0.002 and-1)or CGc
if CGc and NGc and NGc~=CGc then
table.insert(zGc,math.floor(BGc*1000+0.5)/1000)
end
CGc,DGc=NGc or CGc,DGc+math.abs(MGc)
else
AGc=HGc
end
BGc=HGc
if FGc%50==0 then
task.wait()
end
end
if BGc and EGc<=8 then
table.insert(zGc,math.floor(BGc*1000+0.5)/1000)
fGc=fGc or{}
fGc[gGc.Name]={from=math.floor((AGc or 0)*1000+0.5)/1000,len=math.floor(DGc*1000+0.5)/1000,turns=zGc,road=pGc}
end
end
end
if not fGc then
return
end
local OGc=bb.ld.map
P.maps[OGc]=P.maps[OGc]or{}
local PGc=P.maps[OGc].hidden
P.maps[OGc].hidden=fGc
if type(PGc)~=XSe[2370]then
for QGc,RGc in pairs(fGc)do
F.log(1,XSe[3058],string.format(XSe[4639],QGc,RGc.len,tostring(RGc.road),math.floor((#RGc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local SGc,TGc,UGc={},0,0
for VGc,WGc in ipairs(bb.samples)do
local XGc=tostring(WGc.lane)
if not SGc[XGc]then
TGc=TGc+1
end
SGc[XGc]=(SGc[XGc]or 0)+1
UGc=UGc+1
end
bb.laneCount={n=TGc,by=SGc,avg=TGc>0 and UGc/TGc or 1}
if TGc>=2 then
local YGc,ZGc=pcall(gb.laneSep,bb.samples)
local _Gc=P.maps[bb.mapKey()]
if YGc and ZGc and type(_Gc)==XSe[2370]then
_Gc.sep=ZGc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local aHc,bHc={},0
for cHc,dHc in ipairs(workspace._UNITS:GetChildren())do
local eHc=dHc:FindFirstChild(XSe[2442])
if eHc and eHc:FindFirstChild(XSe[4640])and eHc.player.Value==nil and eHc:FindFirstChild(XSe[4641])and dHc:FindFirstChild(XSe[3743])then
local fHc=tostring(eHc.lane.Value)
if not aHc[fHc]then
aHc[fHc]=true
bHc=bHc+1
end
end
end
if bHc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,XSe[3058],XSe[4642])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if bHc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local gHc,hHc={},{}
for iHc,jHc in ipairs(bb.samples)do
if aHc[tostring(jHc.lane)]then
table.insert(gHc,jHc)
end
end
if#gHc==0 then
bb.laneWant=nil
return true
end
for kHc in pairs(aHc)do
table.insert(hHc,kHc)
end
table.sort(hHc)
bb.samples,bb.laneCut=gHc,table.concat(hHc,XSe[2700])
bb.countLanes()
local lHc,mHc=pcall(bb.buildCandidates)
if not lHc then
F.log(1,XSe[2379],XSe[4643]..tostring(mHc))
end
F.log(1,XSe[3058],string.format(XSe[4644],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local nHc,oHc=pcall(bb.planSpots)
bb.planning=nil
if not nHc then
F.log(1,XSe[2379],XSe[4645]..tostring(oHc))
end
end)
end
return true
end
function bb.buildWaves()
local pHc=bb.ld
local qHc=pHc and pHc._dungeon and type(pHc._override_waves)==XSe[2370]and pHc._override_waves or nil
local rHc=pHc and N.Waves[(qHc and qHc.template)or pHc.waves or pHc.id]
local sHc
if type(rHc)==XSe[2370]then
sHc=rHc.override_waves or rHc.waves
if not sHc and rHc.template and N.Waves[rHc.template]then
sHc=N.Waves[rHc.template].waves or N.Waves[rHc.template].override_waves
end
end
bb.waveList=U.list(sHc)
bb.infinite=pHc and(pHc._gamemode==XSe[2395]or pHc.infinite)and gb.unbound(pHc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
return
end
bb.total=(pHc and type(pHc._dungeon)==XSe[2370]and 15)or tonumber(pHc and pHc._override_infinite_bound_waves)or gb.boundEnd(pHc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
function bb.infExtend()
if bb.infinite and bb.wave()+5>bb.total then
bb.total=bb.wave()+10
end
end
function bb.infWave(tHc)
bb.infWaveAt=bb.infWaveAt or{}
bb.infWaveAt[tHc]=bb.infWaveAt[tHc]or U.now()
bb.infExtend()
local uHc=math.floor(tonumber(O.infLeaveWave)or 0)
if uHc>0 and tHc>=uHc and not bb.stopping and ab.partyRole()~=XSe[4075]and bb.kind~=XSe[2840]then
bb.stopping=true
F.log(1,XSe[3058],string.format(XSe[4646],tHc))
local vHc,wHc=pcall(bb.sellAll)
if not vHc then
F.log(1,XSe[2379],XSe[4647]..tostring(wHc))
end
end
if O.trainLeave and not bb.stopping then
local xHc,yHc=pcall(bb.trainLeave,tHc)
if not xHc then
F.log(1,XSe[2379],XSe[4648]..tostring(yHc))
end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=XSe[4075]and bb.kind~=XSe[2840]then
local zHc,AHc=pcall(bb.infStop,tHc)
if not zHc then
F.log(1,XSe[2379],XSe[4649]..tostring(AHc))
end
end
local BHc=W.infTier(tHc-1)
if BHc<=0 or BHc==bb.infTierSeen then
return
end
bb.infTierSeen=BHc
task.delay(5,function()
if not F.alive then
return
end
local CHc=N.prof()
local DHc=CHc and CHc.daily_infinite_reward_claims and CHc.daily_infinite_reward_claims[bb.ld.id]
local EHc=type(DHc)==XSe[2370]and(tonumber(DHc.highest_claimed_wave)or 0)>=BHc and os.time()-(tonumber(DHc.highest_claim_time)or 0)<900
if EHc then
P.infLive=true
end
F.log(1,XSe[3058],string.format(XSe[4650],BHc,EHc and XSe[4651]or XSe[4652]))
end)
end
function bb.infStop(FHc)
local GHc=0
for HHc,IHc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
GHc=math.max(GHc,tonumber(IHc.wave)or 0)
end
if GHc<=0 or FHc<=GHc+1 then
return
end
local JHc=P.train.on
if bb.trainee and JHc and JHc.have+(JHc.got or 0)+(bb.trainTk or 0)<JHc.need then
return
end
if not ab.every(XSe[4653],60)then
return
end
local KHc=W.rec(bb.key)
local LHc=tonumber(KHc.timed)or 0
local MHc=W.INF_PAY
local NHc
if FHc>=(MHc.cap+MHc.less)/MHc.per then
NHc=0
else
local OHc=bb.infWaveAt or{}
local PHc,QHc=OHc[FHc],OHc[FHc-5]
if PHc and QHc and PHc>QHc then
NHc=MHc.per*5/((PHc-QHc)/60)
end
if not NHc then
NHc=(LHc>0 and(KHc.sec or 0)>0)and math.max(0.5,(KHc.gems or 0)/(KHc.sec/60))or 2.5
end
end
local RHc=pcall(W.pick)
local SHc
for THc,UHc in ipairs(RHc and W.lastScored or{})do
if UHc.kind~=XSe[2395]and(not SHc or(UHc.score or 0)>(SHc.score or 0))then
SHc=UHc
end
end
if not SHc or(SHc.score or 0)<=NHc then
return
end
bb.stopping=true
F.log(1,XSe[3058],string.format(XSe[4654],FHc,NHc,SHc.score,SHc.label))
bb.sellAll()
end
function bb.trainLeave(VHc)
local WHc=P.train.on
if not(bb.infinite and bb.trainee and WHc)then
return
end
bb.trainCount()
local XHc=WHc.have+(WHc.got or 0)+(bb.trainTk or 0)
if XHc<WHc.need then
return
end
local YHc,ZHc,_Hc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if YHc and(ZHc or 0)>0 and _Hc>0 and VHc<=_Hc then
F.status(XSe[3708],string.format(XSe[4655],V.name(WHc.id),WHc.what,_Hc))
return
end
bb.stopping=true
F.log(1,XSe[3058],string.format(XSe[4656],V.name(WHc.id),WHc.what,U.fmt(XHc),U.fmt(WHc.need),VHc))
bb.sellAll()
end
function bb.sellAll()
