if(hLc-jLc.p).Magnitude<=jLc.r then
local kLc=tostring(gLc.lane)
eLc[kLc]=(eLc[kLc]or 0)+1
if gLc.prog>(cLc[kLc]or 0)then
cLc[kLc]=gLc.prog
end
break
end
end
end
local lLc,mLc={},0
