w4c.sec,w4c.wave=type(w4c.sec)==XSe[2370]and w4c.sec or{},type(w4c.wave)==XSe[2370]and w4c.wave or{}
if x4c and tonumber(y4c)then
table.insert(w4c.sec,math.floor(y4c+0.5))
end
table.insert(w4c.wave,tonumber(z4c)or 0)
if tonumber(A4c)then
w4c.kills=type(w4c.kills)==XSe[2370]and w4c.kills or{}
table.insert(w4c.kills,math.floor(tonumber(A4c)))
while#w4c.kills>bb.LAYOUT_KEEP do
table.remove(w4c.kills,1)
end
end
while#w4c.sec>bb.LAYOUT_KEEP do
table.remove(w4c.sec,1)
end
while#w4c.wave>bb.LAYOUT_KEEP do
table.remove(w4c.wave,1)
end
end
function bb.layoutJudge(B4c,C4c,D4c,E4c,F4c)
F4c=F4c or XSe[4842]
local G4c,H4c=tonumber(B4c and B4c.runs)or 0,tonumber(C4c and C4c.runs)or 0
if G4c<1 or H4c<bb.LAYOUT_CONTROL then
return nil
end
if E4c and type(B4c.kills)==XSe[2370]and type(C4c.kills)==XSe[2370]and#B4c.kills>=1 and#C4c.kills>=bb.LAYOUT_CONTROL then
local I4c,J4c=bb.labMedian(B4c.kills),bb.labMedian(C4c.kills)
if I4c and J4c and I4c<J4c*0.97 and(#B4c.kills>=2 or I4c<J4c*0.85)then
return string.format(XSe[4843],I4c,J4c,F4c)
end
