local Y4c=X4c and(bb.killsEnd or bb.realKills())or nil
if T4c==XSe[4812]then
local Z4c=bb.bookFor(S4c)
if not Z4c then
return
end
Z4c.real=type(Z4c.real)==XSe[2370]and Z4c.real or{}
bb.layoutAdd(Z4c.real,Q4c,R4c,U4c,Y4c)
local _4c=Z4c.aside==nil and bb.layoutJudge(Z4c.real,V4c.own,W4c,X4c)or nil
if _4c then
Z4c.aside={at=os.time(),why=_4c}
F.log(1,XSe[4741],string.format(XSe[4847],_4c))
end
elseif T4c==XSe[4156]then
V4c.hiveUnit=type(V4c.hiveUnit)==XSe[2370]and V4c.hiveUnit or{}
local a5c=V4c.hiveUnit
bb.layoutAdd(a5c,Q4c,R4c,U4c,Y4c)
local b5c=bb.bookFor(S4c)
local c5c=b5c and type(b5c.real)==XSe[2370]and(tonumber(b5c.real.runs)or 0)>=bb.LAYOUT_CONTROL
local d5c=c5c and b5c.real or V4c.own
local e5c=bb.layoutJudge(a5c,d5c,W4c,X4c,c5c and XSe[4848]or nil)
if e5c then
a5c.aside,a5c.why=os.time(),e5c
F.log(1,XSe[4741],string.format(XSe[4849],e5c))
elseif(tonumber(a5c.runs)or 0)>=bb.HIVE_TRIALS then
local f5c=d5c and bb.layoutJudge(d5c,a5c,W4c,X4c,XSe[4850])
if f5c and b5c and type(bb.hiveUnitPlan)==XSe[2370]then
