b5c.spots[g5c]=h5c
end
b5c.real={runs=a5c.runs,wins=a5c.wins,sec=a5c.sec,wave=a5c.wave,kills=a5c.kills}
b5c.hive,b5c.aside=os.time(),nil
V4c.hiveUnit=nil
F.log(1,XSe[4741],string.format(XSe[4851],f5c))
else
a5c.aside,a5c.why=os.time(),XSe[4852]
F.log(1,XSe[4741],XSe[4853])
end
end
else
V4c[T4c]=type(V4c[T4c])==XSe[2370]and V4c[T4c]or{}
local i5c=V4c[T4c]
bb.layoutAdd(i5c,Q4c,R4c,U4c,Y4c)
if T4c==XSe[4155]and i5c.aside==nil then
local j5c=bb.layoutJudge(i5c,V4c.own,W4c,X4c)
if j5c then
i5c.aside,i5c.why=os.time(),j5c
F.log(1,XSe[4741],string.format(XSe[4854],j5c))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={XSe[4855],XSe[4856],XSe[4857],XSe[4858]}
function bb.controlSpot(k5c,l5c)
if not bb.killZone()then
return nil
end
local m5c=gb.holds
if not m5c(k5c.id)or V.toggleOf(k5c.id)then
return nil
end
local n5c,o5c,p5c,q5c=1,0,0,{}
local r5c=bb.hurtSamples()
for s5c,t5c in ipairs(bb.mine or{})do
local u5c=t5c._stats
local v5c=u5c.id.Value
if u5c:FindFirstChild(XSe[2638])and not V.isFarm(v5c)and not V.allyBuff(v5c)then
local w5c,x5c=U.flat(t5c:GetPivot().Position),u5c.range.Value
if m5c(v5c)and not V.toggleOf(v5c)then
p5c=p5c+1
table.insert(q5c,{p=w5c,r=x5c})
else
for y5c,z5c in ipairs(r5c)do
if(U.flat(z5c.pos)-w5c).Magnitude<=x5c then
n5c,o5c=math.min(n5c,z5c.prog),math.max(o5c,z5c.prog)
end
end
end
end
end
if o5c<=n5c then
n5c,o5c=0.75,0.98
end
local A5c=(l5c or p5c)+1
local B5c=({n5c,o5c,(n5c+o5c)/2,n5c-(o5c-n5c)/2})[A5c]
if not B5c then
return nil
end
local C5c=V.range(k5c.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local D5c={}
for E5c,F5c in ipairs(bb.cands)do
local G5c,H5c,I5c=U.flat(F5c),0,0
for J5c,K5c in ipairs(r5c)do
if(U.flat(K5c.pos)-G5c).Magnitude<=C5c then
I5c=I5c+1
if math.abs(K5c.prog-B5c)<=0.05 then
H5c=H5c+1
local L5c=U.flat(K5c.pos)
for M5c,N5c in ipairs(q5c)do
if(L5c-N5c.p).Magnitude<=N5c.r then
H5c=H5c-0.5
break
end
end
end
end
end
if H5c>0 then
table.insert(D5c,{pos=F5c,sc=H5c,cov=I5c})
end
if E5c%60==0 then
task.wait()
end
end
table.sort(D5c,function(O5c,P5c)
return O5c.sc>P5c.sc
end)
for Q5c,R5c in ipairs(D5c)do
local S5c=bb.valid(R5c.pos,k5c.data)
if S5c then
F.log(1,XSe[4681],string.format(XSe[4859],V.name(k5c.id),bb.CONTROL_WORDS[A5c],math.floor(B5c*100+0.5)))
return S5c,R5c.cov,B5c
end
if Q5c%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(T5c)
