if _5c:FindFirstChild(XSe[2638])and not V.isFarm(a6c)and not V.allyBuff(a6c)and a6c~=T5c.id then
local b6c,c6c=pcall(bb.liveDps,Z5c,a6c)
c6c=b6c and tonumber(c6c)or 0
