if not bb.refusedRun[ddd]then
P.blocked[edd][ddd]=(tonumber(P.blocked[edd][ddd])or 0)+1
bb.refusedRun[ddd]=true
P.blockedAt[edd]=P.blockedAt[edd]or{}
P.blockedAt[edd][ddd]=os.time()
end
if bb.unitRefusals[Ucd.uuid]>=3 then
local fdd=math.max(1,bb.count(Ucd.uuid))
if P.caps[Ucd.uuid]~=fdd or not V.learnedCap(Ucd.uuid)then
P.caps[Ucd.uuid],P.capsAt[Ucd.uuid]=fdd,os.time()
F.log(1,XSe[4681],string.format(XSe[4896],V.name(Ucd.id),fdd))
end
end
elseif bb.unitRefusals[Ucd.uuid]>=3 and(bb.noSpot[Ucd.uuid]or 0)<3 then
bb.noSpot[Ucd.uuid]=3
F.log(1,XSe[4681],string.format(XSe[4897],V.name(Ucd.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,XSe[4681],string.format(XSe[4898],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,XSe[4681],XSe[4899]..ddd..XSe[3353]..V.name(Ucd.id))
F.saveSoon()
end
return false
end
