end
end
table.insert(bb.trialTrace,string.format(XSe[4900],qdd,pdd-(bb.startT or pdd),rdd,table.concat(tdd,XSe[3077]),vdd,udd+Bdd,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[qdd-1]or 0,bb.teamDps or 0))
end
if ndd.lastW and ndd.lastW>0 and ndd.lastWT then
table.insert(ndd.waveSec,pdd-ndd.lastWT)
end
if ndd.paidT and qdd>0 and pdd-ndd.paidT<15 then
table.insert(ndd.skip,pdd-ndd.paidT)
end
ndd.paidT=nil
if qdd>0 then
ndd.alive[tostring(qdd)]=bb.hpAliveRaw or 0
end
ndd.lastW,ndd.lastWT=qdd,pdd
end
local Edd=workspace:FindFirstChild(XSe[4901])
if Edd and qdd>0 then
ndd.timer[tostring(qdd)]=math.max(ndd.timer[tostring(qdd)]or 0,tonumber(Edd.Value)or 0)
end
local Fdd=tonumber(bb.spent)or 0
local Gdd=rdd-(bb.lastMoneyR or rdd)+(Fdd-(bb.lastSpentR or Fdd))
bb.lastMoneyR,bb.lastSpentR=rdd,Fdd
bb.incomeLog=bb.incomeLog or{}
if Gdd>0 then
table.insert(bb.incomeLog,{t=pdd,y=Gdd})
end
while bb.incomeLog[1]and pdd-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local Hdd=0
for Idd,Jdd in ipairs(bb.incomeLog)do
Hdd=Hdd+Jdd.y
end
local Kdd=math.min(30,pdd-(bb.startT or pdd))
bb.incomeRate=Kdd>=8 and Hdd/Kdd or nil
for Ldd,Mdd in ipairs(bb.enemies)do
local Ndd=Mdd.m
local Odd=bb.track[Ndd]
if not Odd then
local Pdd=Ndd._stats
local Qdd=Ndd:FindFirstChildOfClass(XSe[2779])
local Rdd=odd.cfgById[Pdd.id.Value]
local Sdd=Rdd and gb.baseStats(odd,Rdd)
if Qdd and Sdd and qdd>0 then
local Tdd=Sdd*odd.hpRaw*gb.waveScale(odd,qdd,odd.list[qdd])
if Tdd>0 and Qdd.MaxHealth>0 then
table.insert(ndd.hp,Qdd.MaxHealth/Tdd)
end
end
bb.track[Ndd]={t=pdd,p=Mdd.prog,sp=(Pdd:FindFirstChild(XSe[4902])and tonumber(Pdd.speed.Value))or 1}
if Qdd and Qdd.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+Qdd.MaxHealth
end
if qdd>0 then
ndd.spawn[tostring(qdd)]=(ndd.spawn[tostring(qdd)]or 0)+1
ndd.spawnLast[tostring(qdd)]=pdd-(ndd.lastWT or pdd)
end
elseif not Odd.done and pdd-Odd.t>=15 then
Odd.done=true
local Udd=(Mdd.prog-Odd.p)/(pdd-Odd.t)/math.max(0.1,Odd.sp)
if Udd>0.001 and Mdd.prog<0.95 then
table.insert(ndd.walk,Udd)
end
end
end
local Vdd=0
for Wdd,Xdd in ipairs(bb.mine)do
local Ydd=Xdd._stats:FindFirstChild(XSe[2764])
if Ydd then
Vdd=Vdd+Ydd.Value
end
end
for Zdd,_dd in pairs(bb.helperDealt or{})do
if _dd.owner and V.SUMMONER[_dd.owner]and not V.droneHelper(_dd)then
Vdd=Vdd+(tonumber(_dd.v)or 0)
end
end
ndd.potSum=ndd.potSum or 0
if ndd.lastDealtT then
local aed=pdd-ndd.lastDealtT
local bed=0
ndd.potBy=ndd.potBy or{}
ndd.potExp=ndd.potExp or{}
for ced,ded in ipairs(bb.mine)do
local eed=ded._stats
local ged=eed.id.Value
if not V.isFarm(ged)and((eed:FindFirstChild(XSe[4903])and eed.target.Value~=nil)or bb.inReach(ded,ged))then
local hed,ied=pcall(bb.liveDps,ded,ged)
if hed and ied then
bed=bed+ied*aed
local jed=math.max(0.5,V.nudge(ged))
local ked=ied/jed
local led,med=pcall(function()
return V.passive(ged).mark
end)
if led and med and eed:FindFirstChild(XSe[2820])then
ked=ked+(tonumber(med.dot)or 0)*eed.damage.Value
end
ndd.potBy[ged]=(ndd.potBy[ged]or 0)+ked*aed
ndd.potExp[ged]=(ndd.potExp[ged]or 0)+ked*jed*aed
end
end
end
ndd.potWin=(ndd.potWin or 0)+bed
if pdd-(ndd.winT or pdd)>=5 then
local ned=Vdd-(ndd.winDealt or Vdd)
if ndd.potWin>0 and ned>=0 then
ndd.dealtSum=(ndd.dealtSum or 0)+ned
ndd.potSum=ndd.potSum+ndd.potWin
end
ndd.winT,ndd.winDealt,ndd.potWin=pdd,Vdd,0
end
end
if not ndd.winT then
ndd.winT,ndd.winDealt=pdd,Vdd
end
ndd.lastDealtT=pdd
if qdd~=ndd.dpsW and qdd>0 then
ndd.dpsAt[tostring(qdd)]=bb.teamDps or 0
ndd.dpsW=qdd
end
local oed=math.min(1,pdd-(ndd.densT or pdd))
ndd.densT=pdd
for ped,qed in ipairs(bb.enemies)do
local sed=math.min(gb.BINS,math.floor(qed.prog*gb.BINS)+1)
ndd.dens[sed]=(ndd.dens[sed]or 0)+oed
end
local ted=workspace._BASES.player:FindFirstChild(XSe[4904])
local ued=ted and ted:FindFirstChild(XSe[4905])
local ved=ued and ued:FindFirstChildOfClass(XSe[2779])
if ved then
ndd.baseHp=math.max(ndd.baseHp or 0,ved.MaxHealth)
local wed=0
for xed,yed in ipairs(bb.enemies)do
if yed.prog>=0.97 then
local zed=yed.m:FindFirstChildOfClass(XSe[2779])
wed=wed+(zed and zed.MaxHealth or yed.hp)
end
end
if ndd.lastBase and ved.Health<ndd.lastBase and wed>0 and ndd.lastBaseT then
table.insert(ndd.baseRel,(ndd.lastBase-ved.Health)/math.max(0.1,pdd-ndd.lastBaseT)/wed)
end
ndd.lastBase,ndd.lastBaseT=ved.Health,pdd
end
end
function bb.recordMap()
