Kgd.walkN=(tonumber(Kgd.walkN)or 0)+1
Kgd.walk=Jgd and(Jgd+(Hgd-Jgd)*math.max(0.2,1/(Kgd.walkN+1)))or Hgd
gb._walk[Igd]=Kgd.walk
