Dgd(XSe[4925],Bgd(Zgd))
Dgd(XSe[4926],_gd[1]and U.clamp(Bgd(_gd),0.2,6)or nil)
zgd.voteWave=type(zgd.voteWave)==XSe[2370]and zgd.voteWave or{}
