bb.GRIF_ROOM=0.85
function bb.grifSpot(gpd)
local hpd=gpd.data
if gpd._grif then
local ipd=bb.grifNow or bb.grifScan()
if not ipd then
return nil
end
local jpd=ipd.r*bb.GRIF_ROOM
local kpd={}
for lpd,mpd in ipairs(bb.cands or{})do
if(U.flat(mpd)-ipd.p).Magnitude<=jpd then
table.insert(kpd,mpd)
end
end
for npd,opd in ipairs({0.25,0.45,0.65,0.85})do
for ppd=0,11 do
local qpd=ppd*math.pi/6+opd
table.insert(kpd,Vector3 .new(ipd.p.X+math.cos(qpd)*ipd.r*opd,ipd.y,ipd.p.Z+math.sin(qpd)*ipd.r*opd))
end
end
local rpd,spd
for tpd,upd in ipairs(kpd)do
if tpd%40==0 then
task.wait()
end
local vpd=bb.valid(upd,hpd)
local wpd=vpd and(U.flat(vpd)-ipd.p).Magnitude
if wpd and wpd<=jpd and(not spd or wpd<spd)then
rpd,spd=vpd,wpd
end
end
return rpd,rpd and bb.cover(rpd,(tonumber(hpd.range)or 0))or 0
end
local xpd=bb.grifS
local ypd=V.rows(gpd.id)
local zpd=(ypd and ypd[0]and tonumber(ypd[0].range))or tonumber(hpd.range)or 20
local Apd={}
for Bpd,Cpd in ipairs(bb.mine or{})do
if not V.sacFodder(Cpd._stats.id.Value)then
table.insert(Apd,U.flat(Cpd:GetPivot().Position))
end
end
for Dpd,Epd in pairs(bb.layout or{})do
if Dpd~=gpd.id and not V.sacFodder(Dpd)and type(Epd)==XSe[2370]then
for Fpd,Gpd in ipairs(Epd)do
if typeof(Gpd)==XSe[5010]then
table.insert(Apd,U.flat(Gpd))
end
end
end
end
local Hpd={}
for Ipd,Jpd in ipairs(bb.cands or{})do
if Ipd%40==0 then
task.wait()
end
local Kpd=bb.valid(Jpd,hpd)
if Kpd then
table.insert(Hpd,{f=U.flat(Kpd),p=Kpd})
end
end
local Lpd,Mpd
local Npd=math.max(1,math.floor(#Hpd/150))
for Opd=1,#Hpd,Npd do
local Ppd=Hpd[Opd].f
local Qpd=true
for Rpd,Spd in ipairs(Apd)do
if(Spd-Ppd).Magnitude<=zpd+2 then
Qpd=false
break
end
end
if Qpd then
local Tpd=0
for Upd,Vpd in ipairs(Hpd)do
if(Vpd.f-Ppd).Magnitude<=zpd*bb.GRIF_ROOM then
Tpd=Tpd+1
end
end
if not Mpd or Tpd>Mpd then
Lpd,Mpd=Hpd[Opd],Tpd
end
end
if Opd%(Npd*10)==0 then
task.wait()
end
end
if not Lpd or Mpd<4 then
if xpd and not xpd.off then
xpd.off,xpd.offWhy=true,XSe[5011]
F.log(1,XSe[5004],XSe[5012])
end
return nil
end
F.log(2,XSe[5004],string.format(XSe[5013],bb.spotKey(Lpd.p),Mpd))
return Lpd.p,0
end
function bb.grifOpts(Wpd,Xpd,Ypd,Zpd,_pd)
local aqd=bb.grifS
if not(bb.grifOn()and aqd and not aqd.done and not aqd.off)then
