end
local bqd=bb.grifNow
if not bqd or bqd.m~=aqd.m then
return
end
local cqd={}
for dqd,eqd in ipairs(bqd.fodder)do
cqd[eqd]=true
end
for fqd= #Wpd,1,-1 do
if Wpd[fqd].m and cqd[Wpd[fqd].m]then
table.remove(Wpd,fqd)
end
end
aqd.more=false
if not bb.grifLong()then
if not aqd.lateSaid then
aqd.lateSaid=true
F.log(1,XSe[5004],string.format(XSe[5014],bb.GRIF_MIN_WAVES,gb.REINC_LEFT))
end
return
end
local gqd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,gqd*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return
end
local hqd=math.max(1,bqd.need-bqd.yen)
local iqd=(bb.info and tonumber(bb.info.waveSec))or 20
local jqd=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/iqd))
local kqd=math.max(0,hqd-Xpd)/jqd
local lqd=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+kqd/(6*iqd))
if lqd<=0 then
return
end
local mqd=string.format(XSe[5015],U.fmt(bqd.yen),U.fmt(bqd.need))
for nqd,oqd in ipairs(bqd.fodder)do
local pqd=oqd._stats
local qqd=pqd.id.Value
local rqd=V.rows(qqd)
local sqd=tonumber(pqd.upgrade.Value)or 0
local tqd=rqd and rqd[sqd+1]
if tqd and sqd<rqd.max and not((bb.upFail[oqd]or 0)>=3 and U.now()-(bb.upFailAt[oqd]or 0)<60)then
local uqd=1
pcall(function()
uqd=N.USC.calculate_upgrade_cost_multiplier(oqd,N.session())
end)
local vqd=tqd.cost*uqd
aqd.more=true
if bqd.yen<bqd.need then
table.insert(Wpd,{grif=true,cost=vqd,gain=lqd*vqd,m=oqd,what=string.format(XSe[5016],V.name(qqd),sqd+1,mqd)})
end
end
end
if bqd.yen>=bqd.need or bb.fieldCount()>=bb.FIELD_MAX or bb.placePaused()then
return
end
for wqd,xqd in ipairs(aqd.fodder)do
if#(Zpd[xqd.uuid]or{})<V.cap(xqd.u)and(bb.noSpot[xqd.uuid]or 0)<3 then
local yqd=(tonumber(xqd.data.cost)or 0)*Ypd
aqd.more=true
table.insert(Wpd,{place=true,grif=true,cost=yqd,gain=lqd*yqd,e=setmetatable({_grif=true},{__index=xqd}),what=string.format(XSe[5017],V.name(xqd.id),mqd)})
end
end
end
function bb.grifEggGain(zqd,Aqd)
local Bqd=bb.grifS
if not(bb.grifOn()and Bqd and not Bqd.done and not Bqd.off and bb.grifLong())then
return 0
end
local Cqd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,Cqd*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return 0
end
local Dqd=(bb.info and tonumber(bb.info.waveSec))or 20
local Eqd=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/Dqd))
local Fqd=math.max(0,V.GRIF.need+(tonumber(zqd)or 0)-(tonumber(Aqd)or 0))/Eqd
local Gqd=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+Fqd/(6*Dqd))
