function bb.sacrificeOk(Wqd,Xqd)
local Yqd=O.griffinSacrifice
if Yqd==XSe[2502]then
return nil,nil,true
end
if Yqd==XSe[2503]then
return false
end
local Zqd=bb.grifOn()
if Zqd and(bb.grifS.done or bb.grifS.off)then
if bb.grifS.done then
return false
end
Zqd=false
end
if not bb.infinite and bb.total and bb.wave()>=bb.total-2 then
return false
end
local _qd,ard=U.flat(Wqd:GetPivot().Position),tonumber(Xqd.range.Value)or 0
local brd,crd,drd,erd=0,{},0,{}
for frd,grd in ipairs(bb.mine or{})do
local hrd=grd~=Wqd and grd:FindFirstChild(XSe[2442])
local ird=hrd and hrd:FindFirstChild(XSe[2763])and hrd.id.Value
if ird and(U.flat(grd:GetPivot().Position)-_qd).Magnitude<=ard then
if V.sacFodder(ird)then
brd=brd+1
local jrd=hrd:FindFirstChild(XSe[4683])and tonumber(hrd.total_spent.Value)or 0
drd=drd+jrd
erd[grd]=jrd
else
crd[V.name(ird)]=true
end
end
end
if next(crd)then
bb.sacSaid=bb.sacSaid or{}
if not bb.sacSaid[Wqd]then
bb.sacSaid[Wqd]=true
local krd={}
for lrd in pairs(crd)do
table.insert(krd,lrd)
end
table.sort(krd)
F.log(1,XSe[4999],string.format(XSe[5025],V.name(Xqd.id.Value),table.concat(krd,XSe[2494])))
end
return false
end
if brd==0 then
return false
end
if Zqd then
local mrd=bb.grifS
if Wqd~=mrd.m or mrd.cast then
return false
end
local nrd=bb.grifNow
local ord=bb.grifNeed(Wqd)
local prd=drd>=ord-1 or(bb.grifAdds()and nrd~=nil and nrd.m==Wqd and nrd.maxed and not mrd.more)
if not prd then
return false
end
mrd.cast={m=Wqd,at=U.now(),units=erd,yen=drd}
return true,string.format(XSe[5026],brd,brd==1 and XSe[1289]or XSe[2216],U.fmt(drd),U.fmt(ord))
end
return true,string.format(XSe[5027],brd,brd==1 and XSe[1289]or XSe[2216],U.fmt(drd))
end
