if type(rwd)~=XSe[2370]then
return
end
pcall(bb.sampleHelpers,true)
local swd={}
for twd,uwd in pairs(bb.ownDealt or{})do
if not V.isFarm(uwd.id)then
swd[uwd.id]=(swd[uwd.id]or 0)+(tonumber(uwd.v)or 0)
end
end
for vwd,wwd in pairs(bb.helperDealt or{})do
if wwd.owner and V.SUMMONER[wwd.owner]and not V.droneHelper(wwd)then
swd[wwd.owner]=(swd[wwd.owner]or 0)+(tonumber(wwd.v)or 0)
end
