for Bwd,Cwd in pairs(rwd)do
if Cwd>0 then
ywd,zwd=ywd+(swd[Bwd]or 0),zwd+Cwd
local Dwd=tonumber(xwd[Bwd])or Cwd
if Dwd>0 then
table.insert(Awd,{id=Bwd,r=(swd[Bwd]or 0)/Dwd,w=Dwd})
end
end
end
if ywd<=0 or zwd<=0 then
return
end
table.sort(Awd,function(Ewd,Fwd)
return Ewd.r<Fwd.r
end)
