end
if Iwd<=0 then
return nil
end
for Mwd,Nwd in ipairs(Awd)do
if Nwd.id~=Hwd then
Jwd=Jwd+Nwd.w
if Jwd>=Iwd/2 then
return Nwd.r
end
end
end
