P.learn[Owd]=Rwd
end
end
local Uwd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Uwd and next(bb.lastEff)then
