local Vwd=type(P.mapLearn[Uwd])==XSe[2370]and P.mapLearn[Uwd]or{}
for Wwd,Xwd in pairs(bb.lastEff)do
local Ywd=type(Vwd[Wwd])==XSe[2370]and Vwd[Wwd]or{eff=Xwd,n=0,v=6}
if(tonumber(Ywd.v)or 0)<4 then
Ywd.eff,Ywd.v=(tonumber(Ywd.eff)or Xwd)*V.secRescale(Wwd),4
end
if(tonumber(Ywd.v)or 0)<5 then
Ywd.eff,Ywd.v=(tonumber(Ywd.eff)or Xwd)*(V.sumRescale(Wwd)or 1),5
end
if(tonumber(Ywd.v)or 0)<6 then
