end
local Zwd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Ywd.n)or 0))))
Ywd.eff=(tonumber(Ywd.n)or 0)==0 and Xwd or((tonumber(Ywd.eff)or Xwd)+(Xwd-(tonumber(Ywd.eff)or Xwd))*Zwd)
Ywd.n=(tonumber(Ywd.n)or 0)+1
Vwd[Wwd]=Ywd
end
Vwd._at=os.time()
P.mapLearn[Uwd]=Vwd
if U.count(P.mapLearn)>80 then
local _wd,axd
for bxd,cxd in pairs(P.mapLearn)do
if not axd or(tonumber(cxd._at)or 0)<axd then
_wd,axd=bxd,tonumber(cxd._at)or 0
