function bb.baseVerdict(gDd,hDd)
local iDd=(hDd.t or 0)-(gDd.t or 0)
if iDd<bb.BASE_WIN-1 then
return false
end
local jDd=((tonumber(gDd.base)or 0)-(tonumber(hDd.base)or 0))/iDd
if jDd<=0 or(tonumber(hDd.base)or 0)<=0 then
return false
end
local kDd=hDd.base/jDd
local lDd,mDd=0,0
local nDd,oDd=gDd.foes or{},hDd.foes or{}
for pDd,qDd in pairs(oDd)do
if qDd.prog>=bb.BASE_END then
lDd=lDd+qDd.hp
local rDd=nDd[pDd]
if rDd then
mDd=mDd+math.max(0,rDd.hp-qDd.hp)
end
end
end
for sDd,tDd in pairs(nDd)do
if tDd.prog>=bb.BASE_END and not oDd[sDd]then
mDd=mDd+tDd.hp
end
end
if lDd<=0 then
return false
end
local uDd=mDd/iDd
local vDd=uDd>0 and lDd/uDd or math.huge
local wDd={baseTime=kDd,loss=jDd,atEnd=lDd,rate=uDd,killTime=vDd}
return kDd<bb.BASE_SOON and vDd>kDd*bb.BASE_MARGIN,wDd
end
