return
end
bb.drownTarget=IId and HId or nil
if IId then
return
end
local LId=bb.drownState
if not LId or LId.m~=HId.m then
LId={m=HId.m,moves=0,at=0}
bb.drownState=LId
end
if LId.moves>=bb.DROWN_MOVES or U.now()-LId.at<bb.DROWN_EVERY then
return
end
