break
end
end
local cJd=XId:FindFirstChild(XSe[4683])and tonumber(XId.total_spent.Value)or 0
if not _Id and cJd<=2.5*SId and(not UId or cJd<UId)then
TId,UId=WId,cJd
end
end
if TId and bb.money()+gb.SELL_BACK*UId>=SId then
LId.at,LId.moves=U.now(),LId.moves+1
local dJd,eJd=F.request(XSe[2569],XSe[2461],TId)
if eJd==true then
F.log(1,XSe[4681],string.format(XSe[5231],V.name(NId),U.fmt(UId),U.fmt(HId.hp)))
task.wait(0.5)
local fJd,gJd=pcall(bb.place,OId,XSe[5232])
